$(document).ready(function () {
  $("#subscribeForm").submit(function (e) {
    e.preventDefault();
    e = $(this).serialize();
    $.ajax({
      type: "POST",
      url: "subscribe.php",
      data: e,
      success: function (e) {
        $("#subscribe-response").html('<p style="color: green;">' + e + "</p>"),
          $("#subscribeForm")[0].reset();
      },
      error: function () {
        $("#subscribe-response").html(
          '<p style="color: red;">An error occurred. Please try again.</p>'
        );
      },
    });
  });
}),
  $(document).ready(function () {
    $("#feedbackForm").submit(function (e) {
      e.preventDefault();
      e = $(this).serialize();
      $.ajax({
        type: "POST",
        url: "feedback.php",
        data: e,
        success: function (e) {
          $("#feedback-response").html(
            '<p style="color: green;">' + e + "</p>"
          ),
            $("#feedbackForm")[0].reset();
        },
        error: function () {
          $("#feedback-response").html(
            '<p style="color: red;">An error occurred. Please try again.</p>'
          );
        },
      });
    });
  }),
  getIPAddress(),
  window.addEventListener("scroll", function () {
    var e = document.querySelector(".et-hero-tabs-container"),
      t =
        (t = document.querySelector(".et-hero-tabs")).offsetTop +
        t.offsetHeight;
    window.scrollY >= t
      ? e.classList.add("sticky")
      : e.classList.remove("sticky");
  }),
  document.addEventListener("DOMContentLoaded", function () {
    var e = document.getElementById("menu-icon"),
      t = document.getElementById("nav-links");
    e.addEventListener("click", function () {
      t.classList.toggle("show");
    }),
      window.addEventListener("resize", function () {
        768 <= window.innerWidth
          ? t.classList.add("show")
          : t.classList.contains("show") || t.classList.remove("show");
      });
  });
const sub_active = document.getElementById("sub_class");
function onClick() {
  sub_active.classList.add("active");
}
sub_active.addEventListener("click", onClick);
